#ifndef CONJUNTO_H
#define CONJUNTO_H

#define MAX 10

typedef enum {
  FALSO,
  VERDADERO
} TBool;

typedef struct {
  int elementos[MAX];
  int cantidad;
} TConjunto;

void inicializar(TConjunto *c);
void agregar(TConjunto *c, int x);
TBool pertenece(TConjunto c, int x);
int cardinal(TConjunto c);

#endif

#include "conjunto.h"

void inicializar(TConjunto *c) {
  c->cantidad = 0;
}

TBool pertenece(TConjunto c, int x) {
  for (int i = 0; i < c.cantidad; i++) {
    if (c.elementos[i] == x) {
      return VERDADERO;
    }
  }
  return FALSO;
}

void agregar(TConjunto *c, int x) {
  if (pertenece(*c, x) == FALSO) {
    c->elementos[c->cantidad] = x;
    c->cantidad = c->cantidad + 1;
  }
}

int cardinal(TConjunto c) {
  return c.cantidad;
}

