#include <stdio.h>
#include "conjunto.h"

int main() {
  TConjunto c;
  int n;
  int q;
  int x;

  inicializar(&c);
  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%d", &x);
    agregar(&c, x);
  }
  scanf("%d", &q);
  for (int i = 0; i < q; i++) {
    scanf("%d", &x);
    if (pertenece(c, x) == VERDADERO) {
      printf("Pertenece\n");
    } else {
      printf("No pertenece\n");
    }
  }
  return 0;
}

